{
  "narrative_summary": "Self Serve Funnel produced the best outcome in 41% of runs of this model. The link from Customer Acquisition Cost to New Revenue is a fragility worth checking before acting.",
  "story_headlines": {
    "opt_selfserve": "Self Serve Funnel produced the best outcome where acquisition cost stays contained relative to revenue gained.",
    "opt_paid": "Paid Acquisition would need acquisition cost to move much more favourably to produce the best outcome.",
    "opt_partner": "Partner Channel would need a stronger revenue contribution modelled before it produces the best outcome.",
    "opt_outbound": "Outbound Sales would need a materially lower acquisition cost path to produce the best outcome."
  },
  "robustness_explanation": {
    "summary": "The ordering holds in about 64% of variations, a moderate level based on current estimates.",
    "primary_risk": "The link from Customer Acquisition Cost to New Revenue is the main source of fragility here.",
    "stability_factors": [
      "Self Serve Funnel's own modelled outcome stays ahead across a fair range of assumptions"
    ],
    "fragility_factors": [
      "The link from Customer Acquisition Cost to New Revenue could shift which option this model points to"
    ]
  },
  "readiness_rationale": "The comparison is settled enough to act on, though Customer Acquisition Cost is worth confirming since it could shift the picture.",
  "evidence_enhancements": {
    "fac_cac": {
      "specific_action": "Pull actual blended acquisition cost from the last full quarter of channel spend and revenue data.",
      "rationale": "This factor's relationship to revenue is the main source of fragility in this comparison.",
      "evidence_type": "internal_data",
      "decision_hygiene": "Estimate the current acquisition cost yourself before checking the actual figure."
    }
  },
  "scenario_contexts": {
    "edge_cac_growth": {
      "trigger_description": "If Customer Acquisition Cost rises well beyond current levels relative to New Revenue gained...",
      "consequence": "...then this model points to Paid Acquisition rather than Self Serve Funnel."
    }
  },
  "flip_thresholds": [
    {
      "factor_id": "fac_cac",
      "factor_label": "Customer Acquisition Cost",
      "current_display": "420 GBP",
      "flip_display": "610 GBP",
      "narrative": "If Customer Acquisition Cost moves from 420 GBP to 610 GBP, this model points to a different option."
    }
  ],
  "bias_findings": [],
  "key_assumptions": [
    "The link from Customer Acquisition Cost to New Revenue assumes current market conditions hold across all four bets.",
    "The comparison assumes each option's modelled outcome range reflects realistic execution, not best-case delivery."
  ],
  "decision_quality_prompts": [
    {
      "question": "Ten months in, how would you feel about having chosen Self Serve Funnel if Customer Acquisition Cost had risen sharply?",
      "principle": "10-10-10 (Welch)",
      "applies_because": "The options are close enough on these numbers that the emotional weight of the choice over time is worth checking directly."
    },
    {
      "question": "What would need to be true about Paid Acquisition for you to switch away from Self Serve Funnel?",
      "principle": "Consider-the-opposite",
      "applies_because": "Naming the specific conditions that would flip the comparison tests how firm the current reading really is."
    }
  ],
  "pre_mortem": {
    "failure_scenario": "This failed because Customer Acquisition Cost climbed well past expectations, eroding New Revenue faster than Self Serve Funnel's model assumed.",
    "warning_signs": [
      "Acquisition cost per new customer creeping upward each month",
      "New Revenue growth flattening despite steady spend"
    ],
    "mitigation": "Set an acquisition cost checkpoint partway through the quarter before committing the full budget.",
    "grounded_in": ["edge_cac_growth", "fac_cac"],
    "review_trigger": "Reconvene if acquisition cost trends materially above plan before the quarter's midpoint."
  }
}
